INSERT INTO audit_log (actor, action, target, before, after) SELECT 'owner-ruling', 'reverse-search-2026-11-27', sku, json_object('name', name), json_object('name', 'Tsar Molotov X/X+') FROM products WHERE family = 'ace-tsar-molotov' AND supplier_id = 'ace' AND name = 'Hookah No. 26';
UPDATE products SET name = 'Tsar Molotov X/X+', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE family = 'ace-tsar-molotov' AND supplier_id = 'ace' AND name = 'Hookah No. 26';
UPDATE products SET facts_known = json_set(CASE WHEN json_valid(facts_known) THEN facts_known ELSE '{}' END, '$.height_cm', 35, '$.material', 'Aluminium'), updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE family = 'ace-tsar-molotov' AND supplier_id = 'ace' AND (json_extract(facts_known, '$.height_cm') IS NOT 35 OR json_extract(facts_known, '$.material') IS NOT 'Aluminium');
UPDATE products SET details = json_set(details, '$.description', 'A pale stem over a clear, tapered base. Six colour options are listed.'), updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE family = 'ace-tsar-molotov' AND supplier_id = 'ace' AND json_valid(details) AND json_extract(details, '$.description') = 'A pale stem over a clear, tapered base, pictured by Ace with a hose and a bowl. Six colour options are listed.';
